select case when s.rating >= 3.6 then 'high' when s.rating >= 2.3 then 'mid' else 'low' end as rating_bucket, s.country, round(avg(i.quantity), 2) as avg_quantity from inventory i left outer join products p on i.product_id = p.id join suppliers s on p.supplier_id = s.id where s.city = 'Bangkok' group by case when s.rating >= 3.6 then 'high' when s.rating >= 2.3 then 'mid' else 'low' end, s.country order by country
